            ["fr-FR"] = new[] { "Dégâts de lancer normal : {0}\nLancer renforcé : {1} · Chance : {2}%\nAvant les critiques et les défenses de la cible ; les attaques de rappel sont calculées séparément.", "Dégâts de décharge normale : {0}\nAvant les critiques et les défenses de la cible ; hors décharges renforcées.", "Réserve : {0}/{1}\nCycle automatique : {2} s · Décharges : {3}\nSans consommation : {4}%\nEn combat : récupère {5} toutes les {6} s\nUne cible valide est nécessaire.", "{0}. {1} · MP {2} · {4}/{5}\nMP par utilisation : {2} · MP pour {3} utilisations\nCharges : {4}/{5} · Nouveau cycle : {6} s\nSans régénération ni limites de lancement.", "Brûlure, dégâts de référence par cumul : {0}\nIntervalle : {1} s · Limite : {2}\nAvant les multiplicateurs de la source et les impacts. Nécessite une source de brûlure.", "Épées disponibles : {0}/{1}\nRéserve remplie au début du combat. Ramasser les épées la restaure aussi.", "{0} : {1} dégâts par projectile\nDéclenchement normal avec le mana actuel : {2} MP · Cycle de charge : {3} s · Projectiles : {4}\nAvant critiques et défenses ; déclenchements spéciaux et répétitions séparés.", "{0} : {1} dégâts par lame\nCycle : {2} s · Cibles par vague : {3} · Vagues : {4}\nChaque dégât de électrocution réduit l’attente de {5} s. Nécessite des cibles proches. Avant les défenses.", "{0} : {1} dégâts par balle normale\nBalle renforcée : {2}\nRéférences avant les défenses ; le renforcement exige son effet propre. Coups supplémentaires et traînées brûlantes séparés.", "Électrocution de référence par cumul : {0}\nLimite : {1}. Les dégâts sont calculés à la réapplication ou à la fin selon le temps accumulé, sans pulsations périodiques. Valeur pour une durée de base. Nécessite une source de électrocution ; hors multiplicateurs de la source et défenses.", "Bonus d’attributs\nAucun résultat calculé pour cet effet. Ces bonus seuls ne l’activent pas." },
            ["it-IT"] = new[] { "Danno del lancio normale: {0}\nLancio potenziato: {1} · Probabilità: {2}%\nPrima di critici e difese del bersaglio; gli attacchi di richiamo sono separati.", "Danni della scarica normale: {0}\nPrima dei critici e delle difese del bersaglio; senza scariche potenziate.", "Riserva: {0}/{1}\nCiclo automatico: {2} s · Scariche: {3}\nNessun consumo: {4}%\nIn combattimento: recupera {5} ogni {6} s\nServe un bersaglio valido.", "{0}. {1} · MP {2} · {4}/{5}\nMP per uso: {2} · MP per {3} usi\nCariche: {4}/{5} · Nuovo ciclo: {6} s\nEsclude rigenerazione e limiti di lancio.", "Ustione, danni di riferimento per accumulo: {0}\nIntervallo: {1} s · Limite: {2}\nPrima dei moltiplicatori della fonte e del calcolo del colpo. Serve una fonte di ustione.", "Spade disponibili: {0}/{1}\nSi ripristinano a inizio combattimento. Anche raccogliere spade recupera la riserva.", "{0}: {1} danni per proiettile\nAttivazione normale con il mana attuale: {2} MP · Ciclo di carica: {3} s · Proiettili: {4}\nPrima di critici e difese; attivazioni speciali e ripetizioni sono separate.", "{0}: {1} danni per lama\nCiclo: {2} s · Bersagli per ondata: {3} · Ondate: {4}\nOgni danno da elettrocuzione riduce l’attesa di {5} s. Richiede bersagli vicini. Prima delle difese.", "{0}: {1} danni del proiettile normale\nProiettile potenziato: {2}\nValori di riferimento prima delle difese; il potenziamento richiede il relativo effetto. Colpi aggiuntivi e scie ardenti separati.", "Elettrocuzione di riferimento per accumulo: {0}\nLimite: {1}. I danni si calcolano alla riapplicazione o alla fine in base al tempo accumulato, non a intervalli regolari. Valore per una durata base. Richiede una fonte di elettrocuzione; esclusi moltiplicatori della fonte e difese.", "Bonus agli attributi\nNessun risultato calcolato per questo effetto. Questi bonus da soli non lo attivano." },
            ["pl-PL"] = new[] { "Obrażenia zwykłego rzutu: {0}\nWzmocniony rzut: {1} · Szansa: {2}%\nPrzed trafieniami krytycznymi i obroną celu; ataki powrotne są liczone osobno.", "Obrażenia zwykłego wyładowania: {0}\nPrzed trafieniami krytycznymi i obroną celu; bez wzmocnionych wyładowań.", "Zapas: {0}/{1}\nCykl automatyczny: {2} s · Wyładowania: {3}\nBez zużycia: {4}%\nW walce: odzyskuje {5} co {6} s\nWymaga odpowiedniego celu.", "{0}. {1} · MP {2} · {4}/{5}\nMP na użycie: {2} · MP na {3} użyć\nŁadunki: {4}/{5} · Nowy cykl: {6} s\nBez regeneracji i ograniczeń rzucania.", "Podpalenie, obrażenia orientacyjne na kumulację: {0}\nOdstęp: {1} s · Limit: {2}\nPrzed mnożnikami źródła i rozliczeniem trafienia. Wymaga źródła podpalenia.", "Dostępne miecze: {0}/{1}\nZapas odnawia się na początku walki. Podnoszenie mieczy również go uzupełnia.", "{0}: {1} obrażeń na pocisk\nZwykłe wyzwolenie przy obecnej manie: {2} MP · Cykl ładowania: {3} s · Pociski: {4}\nPrzed trafieniami krytycznymi i obroną; specjalne wyzwolenia i powtórzenia są osobne.", "{0}: {1} obrażeń na ostrze\nCykl: {2} s · Cele na falę: {3} · Fale: {4}\nKażde obrażenia od porażenia prądem skracają oczekiwanie o {5} s. Wymaga pobliskich celów. Przed obroną.", "{0}: {1} obrażeń zwykłego pocisku\nWzmocniony pocisk: {2}\nWartości przed obroną; wzmocnienie wymaga odpowiedniego efektu. Dodatkowe trafienia i płonące smugi liczone osobno.", "Porażenie prądem — obrażenia odniesienia na kumulację: {0}\nLimit: {1}. Obrażenia są rozliczane przy ponownym nałożeniu lub końcu według zgromadzonego czasu, nie cyklicznie. Wartość dla jednego bazowego okresu. Wymaga źródła porażenia prądem; bez mnożników źródła i obrony.", "Premie do atrybutów\nBrak obliczonego wyniku dla tego efektu. Same premie go nie aktywują." },
