            ["ru-RU"] = new[] { "Урон обычного броска: {0}\nУсиленный бросок: {1} · Шанс: {2}%\nДо критических попаданий и защиты цели; возвратные атаки рассчитываются отдельно.", "Урон обычного разряда: {0}\nДо критических попаданий и защиты цели; без усиленных разрядов.", "Запас: {0}/{1}\nАвтоматический цикл: {2} с · Разрядов: {3}\nБез расхода: {4}%\nВ бою: восстанавливает {5} каждые {6} с\nТребуется подходящая цель.", "{0}. {1} · MP {2} · {4}/{5}\nMP за применение: {2} · MP хватит на {3} применений\nЗаряды: {4}/{5} · Новый цикл: {6} с\nБез учёта восстановления и ограничений применения.", "Горение, справочный урон за слой: {0}\nИнтервал: {1} с · Предел слоёв: {2}\nДо множителей источника и расчёта попадания. Нужен источник горения.", "Доступные мечи: {0}/{1}\nЗапас восстанавливается в начале боя. Подбор мечей также его пополняет.", "{0}: {1} урона за снаряд\nОбычное срабатывание с текущей маной: {2} MP · Цикл заряда: {3} с · Снаряды: {4}\nДо критических попаданий и защиты; особые и повторные срабатывания отдельно.", "{0}: {1} урона за клинок\nЦикл: {2} с · Целей за волну: {3} · Волн: {4}\nКаждый урон от электрошока сокращает ожидание на {5} с. Нужны цели поблизости. До защиты цели.", "{0}: {1} урона обычного снаряда\nУсиленный снаряд: {2}\nСправочные значения до защиты; усиление требует соответствующего эффекта. Дополнительные попадания и горящие следы отдельно.", "Справочный урон электрошока за слой: {0}\nПредел слоёв: {1}. Урон рассчитывается при повторном наложении или завершении по накопленному времени, а не периодическими тактами. Значение за один базовый период. Нужен источник электрошока; без множителей источника и защиты.", "Бонусы характеристик\nДля этого эффекта нет рассчитанного результата. Сами бонусы его не активируют." },
